  1	import * as fs from 'node:fs';
  2	import * as path from 'node:path';
  3	import type { AppConfig } from '../../config/config.types.js';
  4	import { readJsonFile, writeJsonFile, FileNotFoundError } from '../../storage/json-storage.js';
  5	import { toKebabCase, isValidKebabCase } from '../../utils/slug.js';
  6	import { NotFoundError } from '../../errors.js';
  7	// `import type` used here intentionally: RepositoryManager is injected via the constructor
  8	// and never constructed inside this module, so no runtime import is needed. TypeScript
  9	// erases the type import entirely, avoiding any potential circular-reference warning.
 10	import type { RepositoryManager } from '../repository/repository.manager.js';
 11	import type { ProjectData, ProjectIndex, ProjectIndexEntry, ProjectWorkspace } from './project.types.js';
 12	import { STABLE_WORKSPACE_ID } from '../workspace/workspace.types.js';
 13	
 14	const INDEX_FILE = 'projects-index.json';
 15	const PROJECTS_SUBDIR = 'projects';
 16	const SCHEMA_VERSION = 1;
 17	
 18	const DEFAULT_INDEX: ProjectIndex = { Projects: [], SchemaVersion: SCHEMA_VERSION };
 19	
 20	/**
 21	 * Provides CRUD operations over the persisted project store.
 22	 *
 23	 * Uses a dual-file storage strategy:
 24	 * - A lightweight index (`projects-index.json`) for fast listing.
 25	 * - Individual project files (`projects/{id}.json`) for full project data.
 26	 *
 27	 * Every public method is stateless — it re-reads from disk on each call so
 28	 * that concurrent writes from other processes are always reflected.
 29	 */
 30	export class ProjectManager {
 31	    private readonly indexPath: string;
 32	    private readonly projectsDir: string;
 33	
 34	    constructor(
 35	        private readonly config: AppConfig,
 36	        private readonly repositoryManager: RepositoryManager,
 37	    ) {
 38	        this.indexPath = path.join(config.storageFolder, INDEX_FILE);
 39	        this.projectsDir = path.join(config.storageFolder, PROJECTS_SUBDIR);
 40	    }
 41	
 42	    // -------------------------------------------------------------------------
 43	    // Private helpers
 44	    // -------------------------------------------------------------------------
 45	
 46	    private loadIndex(): ProjectIndex {
 47	        try {
 48	            return readJsonFile<ProjectIndex>(this.indexPath);
 49	        } catch (err) {
 50	            if (err instanceof FileNotFoundError) {
 51	                return { ...DEFAULT_INDEX, Projects: [] };
 52	            }
 53	            throw err;
 54	        }
 55	    }
 56	
 57	    private saveIndex(index: ProjectIndex): void {
 58	        writeJsonFile(this.indexPath, index);
 59	    }
 60	
 61	    private projectFilePath(id: string): string {
 62	        return path.join(this.projectsDir, `${id}.json`);
 63	    }
 64	
 65	    private loadProject(id: string): ProjectData | undefined {
 66	        try {
 67	            return readJsonFile<ProjectData>(this.projectFilePath(id));
 68	        } catch (err) {
 69	            if (err instanceof FileNotFoundError) {
 70	                return undefined;
 71	            }
 72	            throw err;
 73	        }
 74	    }
 75	
 76	    private saveProject(data: ProjectData): void {
 77	        writeJsonFile(this.projectFilePath(data.Id), data);
 78	    }
 79	
 80	    private now(): string {
 81	        return new Date().toISOString();
 82	    }
 83	
 84	    // -------------------------------------------------------------------------
 85	    // Public API
 86	    // -------------------------------------------------------------------------
 87	
 88	    /**
 89	     * Returns all projects from the index.
 90	     */
 91	    list(): ProjectIndexEntry[] {
 92	        return this.loadIndex().Projects;
 93	    }
 94	
 95	    /**
 96	     * Reads and returns the full project data, or `undefined` if not found.
 97	     */
 98	    getById(id: string): ProjectData | undefined {
 99	        return this.loadProject(id);
100	    }

101	
102	    /**
103	     * Creates a new project.
104	     *
105	     * - When `id` is omitted, it is generated from `name` via `toKebabCase()`.
106	     * - When `id` is provided explicitly it is validated via `isValidKebabCase()`
107	     *   after trimming. Path-traversal sequences and invalid formats are rejected.
108	     * - Validates that all `repositoryIds` exist via the RepositoryManager.
109	     * - Auto-creates a STABLE workspace with correct timestamps.
110	     * - Saves the project file and updates the project index.
111	     *
112	     * @throws {Error} If the explicit `id` is not valid kebab-case.
113	     * @throws {Error} If `name` produces an empty slug and no `id` was given.
114	     * @throws {Error} If any repository ID does not exist.
115	     * @throws {Error} If a project with the resolved ID already exists.
116	     */
117	    create(
118	        name: string,
119	        repositoryIds: string[],
120	        description?: string,
121	        id?: string,
122	    ): ProjectData {
123	        let resolvedId = id;
124	        if (resolvedId) {
125	            resolvedId = resolvedId.trim();
126	            if (!isValidKebabCase(resolvedId)) {
127	                throw new Error(
128	                    `Invalid project ID "${resolvedId}": must be a valid kebab-case string ` +
129	                    `(lowercase alphanumeric segments separated by single hyphens).`
130	                );
131	            }
132	        } else {
133	            resolvedId = toKebabCase(name);
134	            if (resolvedId === '') {
135	                throw new Error(
136	                    `Cannot generate a project ID from name "${name}": the name produced an empty slug. ` +
137	                    `Please provide an explicit ID.`
138	                );
139	            }
140	        }
141	
142	        for (const repoId of repositoryIds) {
143	            if (!this.repositoryManager.exists(repoId)) {
144	                throw new Error(`Repository with ID "${repoId}" does not exist.`);
145	            }
146	        }
147	
148	        const index = this.loadIndex();
149	        if (index.Projects.some((p) => p.Id === resolvedId)) {
150	            throw new Error(`A project with ID "${resolvedId}" already exists.`);
151	        }
152	
153	        const timestamp = this.now();
154	        const project: ProjectData = {
155	            Id: resolvedId,
156	            Name: name,
157	            Description: description ?? '',
158	            DateCreated: timestamp,
159	            DateModified: timestamp,
160	            Repositories: [...repositoryIds],
161	            Workspaces: {
162	                [STABLE_WORKSPACE_ID]: {
163	                    Description: 'Stable workspace',
164	                    DateCreated: timestamp,
165	                    DateModified: timestamp,
166	                },
167	            },
168	            SchemaVersion: SCHEMA_VERSION,
169	        };
170	
171	        this.saveProject(project);
172	        index.Projects.push({ Id: resolvedId, Name: name });
173	        this.saveIndex(index);
174	        return project;
175	    }
176	
177	    /**
178	     * Updates mutable project fields (`Name` and/or `Description`).
179	     * Always updates `DateModified`. Keeps the index in sync when `Name` changes.
180	     *
181	     * @throws {Error} If no project with the given ID exists.
182	     */
183	    update(id: string, changes: { Name?: string; Description?: string }): ProjectData {
184	        const project = this.loadProject(id);
185	        if (!project) {
186	            throw new NotFoundError(`Cannot update: project with ID "${id}" does not exist.`);
187	        }
188	
189	        if (changes.Name !== undefined) {
190	            project.Name = changes.Name;
191	        }
192	        if (changes.Description !== undefined) {
193	            project.Description = changes.Description;
194	        }
195	        project.DateModified = this.now();
196	        this.saveProject(project);
197	
198	        if (changes.Name !== undefined) {
199	            const index = this.loadIndex();
200	            const entry = index.Projects.find((p) => p.Id === id);
201	            if (entry) {
202	                entry.Name = changes.Name;
203	                this.saveIndex(index);
204	            }
205	        }
206	
207	        return project;
208	    }
209	
210	    /**
211	     * Renames a project by changing its ID.
212	     *
213	     * - Validates `newId` via `isValidKebabCase()` after trimming.
214	     * - Updates the `Id` field inside the project data file.
215	     * - Renames the project JSON file on disk (old file is deleted).
216	     * - Updates the project index entry.
217	     * - Updates `DateModified`.
218	     *
219	     * @throws {Error} If `newId` is not valid kebab-case.
220	     * @throws {Error} If no project with `oldId` exists.
221	     * @throws {Error} If a project with `newId` already exists.
222	     */
223	    rename(oldId: string, newId: string): ProjectData {
224	        newId = newId.trim();
225	        if (!isValidKebabCase(newId)) {
226	            throw new Error(
227	                `Invalid project ID "${newId}": must be a valid kebab-case string ` +
228	                `(lowercase alphanumeric segments separated by single hyphens).`
229	            );
230	        }
231	
232	        const project = this.loadProject(oldId);
233	        if (!project) {
234	            throw new NotFoundError(`Cannot rename: project with ID "${oldId}" does not exist.`);
235	        }
236	
237	        const index = this.loadIndex();
238	        if (index.Projects.some((p) => p.Id === newId)) {
239	            throw new Error(`Cannot rename: a project with ID "${newId}" already exists.`);
240	        }
241	
242	        const oldFilePath = this.projectFilePath(oldId);
243	        const newFilePath = this.projectFilePath(newId);
244	
245	        project.Id = newId;
246	        project.DateModified = this.now();
247	
248	        // Write the new file first so no data is lost if the subsequent
249	        // delete or index write fails.
250	        writeJsonFile(newFilePath, project);
251	        fs.unlinkSync(oldFilePath);
252	
253	        const entry = index.Projects.find((p) => p.Id === oldId);
254	        if (entry) {
255	            entry.Id = newId;
256	        }
257	        this.saveIndex(index);
258	
259	        return project;
260	    }
261	
262	    /**
263	     * Removes a project from the index and deletes the project JSON file.
264	     *
265	     * @throws {Error} If no project with the given ID exists in the index.
266	     */
267	    remove(id: string): void {
268	        const index = this.loadIndex();
269	        const entryIndex = index.Projects.findIndex((p) => p.Id === id);
270	        if (entryIndex === -1) {
271	            throw new NotFoundError(`Cannot remove: project with ID "${id}" does not exist.`);
272	        }
273	
274	        const filePath = this.projectFilePath(id);
275	        if (fs.existsSync(filePath)) {
276	            fs.unlinkSync(filePath);
277	        }
278	
279	        index.Projects.splice(entryIndex, 1);
280	        this.saveIndex(index);
281	    }
282	
283	    /**
284	     * Adds a repository to the project's repository list.
285	     * Updates `DateModified`.
286	     *
287	     * @throws {Error} If the project does not exist.
288	     * @throws {Error} If the repository ID does not exist.
289	     * @throws {Error} If the repository is already listed in the project.
290	     */
291	    addRepository(projectId: string, repositoryId: string): ProjectData {
292	        const project = this.loadProject(projectId);
293	        if (!project) {
294	            throw new NotFoundError(`Cannot addRepository: project with ID "${projectId}" does not exist.`);
295	        }
296	
297	        if (!this.repositoryManager.exists(repositoryId)) {
298	            throw new NotFoundError(`Repository with ID "${repositoryId}" does not exist.`);
299	        }

