496	test('CRUD round-trip: create → list → getById → update → rename → addRepository → removeRepository → remove', () => {
497	    const base = makeTempDir();
498	    const { repoManager, projectManager } = makeManagers(base);
499	    repoManager.add({ url: 'https://github.com/user/repo-a.git' });
500	    repoManager.add({ url: 'https://github.com/user/repo-b.git' });
501	
502	    // create
503	    const created = projectManager.create('My Project', ['repo-a'], 'Initial desc', 'my-project');
504	    assert.strictEqual(created.Id, 'my-project');
505	    assert.strictEqual(created.Name, 'My Project');
506	    assert.strictEqual(created.Description, 'Initial desc');
507	    assert.ok(created.Repositories.includes('repo-a'));
508	    assert.ok('STABLE' in created.Workspaces);
509	
510	    // list & index
511	    const entries = projectManager.list();
512	    assert.strictEqual(entries.length, 1);
513	    assert.strictEqual(entries[0].Id, 'my-project');
514	    assert.strictEqual(entries[0].Name, 'My Project');
515	
516	    // getById
517	    const fetched = projectManager.getById('my-project');
518	    assert.ok(fetched !== undefined);
519	    assert.strictEqual(fetched.Id, 'my-project');
520	
521	    // update
522	    const updated = projectManager.update('my-project', { Name: 'Renamed Project', Description: 'Updated desc' });
523	    assert.strictEqual(updated.Name, 'Renamed Project');
524	    assert.strictEqual(updated.Description, 'Updated desc');
525	    assert.ok(updated.DateModified >= created.DateModified);
526	    assert.strictEqual(projectManager.list().find((e) => e.Id === 'my-project')?.Name, 'Renamed Project');
527	
528	    // addRepository
529	    const afterAdd = projectManager.addRepository('my-project', 'repo-b');
530	    assert.ok(afterAdd.Repositories.includes('repo-b'));
531	    assert.ok(afterAdd.DateModified >= updated.DateModified);
532	
533	    // removeRepository
534	    const afterRemove = projectManager.removeRepository('my-project', 'repo-b');
535	    assert.ok(!afterRemove.Repositories.includes('repo-b'));
536	    assert.ok(afterRemove.DateModified >= afterAdd.DateModified);
537	
538	    // rename
