540	    assert.strictEqual(renamed.Id, 'new-id');
541	    assert.ok(projectManager.getById('my-project') === undefined, 'old ID should be gone');
542	    assert.ok(projectManager.getById('new-id') !== undefined, 'new ID should exist');
543	    const indexAfterRename = projectManager.list();
544	    assert.ok(indexAfterRename.some((e) => e.Id === 'new-id'));
